    if (!head || !head.next) return head;
    let prev = null;
    let slow = head, fast = head;
    while (fast !== null && fast.next !== null) {
        prev = slow;
        slow = slow.next;
        fast = fast.next.next;
    }
    prev.next = null;
    const l1 = sortList(head);
    const l2 = sortList(slow);
